mapper.sql:
WHERE br.deleted = 0
AND br.record_date BETWEEN #{dto.recordStartDate} AND #{dto.recordEndDate}
AND br.record_source like concat('%', #{dto.recordSource}, '%')
AND br.dictionary_snapshot_status=1 AND br.record_type_name IS NULL AND br.dictionary_snapshot_status=0
AND br.dictionary_snapshot_status = 1 AND CAST(br.record_type_name AS BINARY) IN CAST(#{name} AS BINARY)
AND br.record_category = #{dto.recordCategory}
AND br.is_statistics = 1
AND br.amount >= #{dto.mixAmount}
AND br.amount <= #{dto.maxAmount}
AND EXISTS (SELECT 1 FROM bookkeeping_record_tag_snapshot ts WHERE ts.record_id=br.id AND ts.dict_type = CASE WHEN br.record_category=1 THEN 4001 ELSE 4011 END AND CAST(ts.tag_name AS BINARY) IN CAST(#{name} AS BINARY))

mapper.select:
SELECT IFNULL(SUM(amount), 0) AS totalAmount, count(*) AS totalRecordNum FROM bookkeeping_records WHERE deleted = 0 AND record_date BETWEEN #{dto.currentStartMonth} AND #{dto.currentEndMonth}
AND record_category = #{dto.recordCategory}
AND is_statistics = 1
AND dictionary_snapshot_status=1 AND record_type_name IS NULL AND dictionary_snapshot_status=0
AND dictionary_snapshot_status=1 AND CAST(record_type_name AS BINARY) IN CAST(#{name} AS BINARY)
AND EXISTS (SELECT 1 FROM bookkeeping_record_tag_snapshot tag_filter WHERE tag_filter.record_id=bookkeeping_records.id AND tag_filter.dict_type=CASE WHEN bookkeeping_records.record_category=1 THEN 4001 ELSE 4011 END AND CAST(tag_filter.tag_name AS BINARY) IN CAST(#{name} AS BINARY))

select id, user_id, expense_user_id, record_category, record_type, record_type_id, record_type_name, dictionary_snapshot_status, record_source, record_date, record_time, amount from bookkeeping_records WHERE deleted = 0 and record_category = #{dto.recordCategory} AND record_date BETWEEN #{dto.currentStartMonth} AND #{dto.currentEndMonth}
AND is_statistics = 1
AND dictionary_snapshot_status=1 AND record_type_name IS NULL AND dictionary_snapshot_status=0
AND dictionary_snapshot_status=1 AND CAST(record_type_name AS BINARY) IN CAST(#{name} AS BINARY)
AND EXISTS (SELECT 1 FROM bookkeeping_record_tag_snapshot tag_filter WHERE tag_filter.record_id=bookkeeping_records.id AND tag_filter.dict_type=CASE WHEN bookkeeping_records.record_category=1 THEN 4001 ELSE 4011 END AND CAST(tag_filter.tag_name AS BINARY) IN CAST(#{name} AS BINARY))
order by amount desc limit ${dto.limit}
